      state.catalog = catalog;
      state.status = "catalog";
      var plan = planByCode(state.planCode);
      state.selection = plan && plan.selfService ? PS.selection.initial(catalog, { plan: plan.code, period: state.period }) : null;
      if (!state.selection) {
