      host.dataset.pricingState = "catalog";
      setNotice([]);
      renderAll();
    }).catch(function () {
      state.status = "offline";
      host.dataset.pricingState = "fallback";
      renderAll();
    });
  }

  function initStickyTop(main) {
    var header = document.querySelector(".header");
    var queued = false;
    var sync = function () {
      queued = false;
